def handle(query, state):
    import shlex

    url = (query.get('url') or [''])[0]
    if not url:
        return 400, {'Content-Type': 'text/plain'}, 'missing url parameter'

    # Simulate the shell command the proxy would run:
    #   convert <url> -thumbnail 128x128 /tmp/thumb.jpg
    # The url is interpolated directly into the command string — classic injection sink.
    full_cmd = 'convert ' + url + ' -thumbnail 128x128 /tmp/thumb.jpg'

    # Split on ';' to obtain pipeline stages (mirrors naive shell execution).
    stages = full_cmd.split(';')

    output_parts = []
    for stage in stages:
        stage = stage.strip()
        if not stage:
            continue
        try:
            tokens = shlex.split(stage)
        except ValueError:
            tokens = stage.split()
        if not tokens:
            continue

        cmd_name = tokens[0]

        if cmd_name == 'convert':
            # tokens[1] is the source image URL/path
            src = tokens[1] if len(tokens) > 1 else ''
            files = state.get('files', {})
            if src in files:
                content = files[src]
                # Return thumbnail metadata, not the raw content
                output_parts.append(
                    '[thumbnail: 128x128 source=' + src +
                    ' size=' + str(len(content)) + 'B]'
                )
            else:
                output_parts.append('[thumbnail: source not found: ' + src + ']')

        elif cmd_name == 'cat':
            # tokens[1] is the file path to read
            path = tokens[1] if len(tokens) > 1 else ''
            files = state.get('files', {})
            if path in files:
                output_parts.append(str(files[path]))
            else:
                output_parts.append('cat: ' + path + ': No such file or directory')

        elif cmd_name == 'echo':
            output_parts.append(' '.join(tokens[1:]))

        # All other commands produce no output (silently ignored)

    body = '\n'.join(output_parts) if output_parts else ''
    return 200, {'Content-Type': 'text/plain'}, body
